#define MAX 5
typedef struct {
    int items[MAX];
    int top; // index of the top element, -1 means empty
} Stack;

int push(Stack* s, int value) {
    if (s->top == MAX - 1) return 0; // overflow
    s->items[++(s->top)] = value;
    return 1;
}

int pop(Stack* s, int* out) {
    if (s->top == -1) return 0; // underflow
    *out = s->items[(s->top)--];
    return 1;
}

